insert into public.offers (source_key, supermarket_id, product_id, type, price, offer_date, expiry_date, source)
select s.source_key, sm.id, p.id, s.type, s.price::numeric(10,2), s.offer_date::date, s.expiry_date::date, s.source
from seed s
join public.supermarkets sm on sm.name = s.supermarket_name
join public.products p on p.name = s.product_name and p.mode = 'taglio'
on conflict (source_key) do update set
  supermarket_id = excluded.supermarket_id,
  product_id = excluded.product_id,
  type = excluded.type,
  price = excluded.price,
  offer_date = excluded.offer_date,
  expiry_date = excluded.expiry_date,
  source = excluded.source;
